// TestEveryStructuralStubHasReachabilityVerdict is Task 4's guard: every
// method actualRemoteUnsupportedStubs finds (the same structural-stub
// population remoteUnsupportedAllowlist's own completeness guard uses) must
// have an entry in remoteReachabilityRegistry, and every registry entry must
// still correspond to a real structural stub — no third state, no silent
// additions, same shape as that guard and as scripts/ci-test-legs.sh's C5
// ratchet.
func TestEveryStructuralStubHasReachabilityVerdict(t *testing.T) {
	actual := actualRemoteUnsupportedStubs(t)

	var missing []string
	for name := range actual {
		if _, ok := remoteReachabilityRegistry[name]; !ok {
			missing = append(missing, name)
		}
	}
	sort.Strings(missing)

	var stale []string
	for name := range remoteReachabilityRegistry {
		if !actual[name] {
			stale = append(stale, name)
		}
	}
	sort.Strings(stale)

	if len(missing) > 0 {
		t.Errorf("found %d structurally-stub RemoteStorage method(s) with NO reachability verdict in "+
			"remoteReachabilityRegistry (internal/storage/store/remote_reachability_registry_test.go): %v\n"+
			"Every new stub-shaped method must be classified reachabilityLive (name the CLI command and the "+
			"failure mode), reachabilityDead (name why every path is guarded/server-only/callerless), or "+
			"reachabilityUnresolved (name what evidence would settle it) before it can be merged — trace the "+
			"method's actual internal/core caller(s) and CLI/HTTP/gRPC reachability under storage.type: remote, "+
			"don't guess.", len(missing), missing)
	}
	if len(stale) > 0 {
		t.Errorf("found %d remoteReachabilityRegistry entr(y/ies) that no longer correspond to a structural stub "+
			"(the method was fixed, removed, or now reaches the network): %v\nRemove these entries.", len(stale), stale)
	}
}
